package com.raival.compose.file.explorer.screen.viewer.video.mpv

/**
 * Rewrites mpv user shaders so mobile GLSL ES compilers accept them, without changing what
 * they compute. Applied to bundled Anime4K shaders and to imported user shaders.
 *
 * Adreno drivers reject Anime4K as generated by libplacebo ("ERROR: 0:93: 'MAIN..."), while
 * conformant compilers (ANGLE, desktop) accept it. Two preprocessor corner cases are involved:
 *
 * 1. Comments after `#define` (`#define KERNELSIZE 5 //Kernel size...`). The standard strips
 *    comments before macro processing; a driver that keeps them breaks every line using the
 *    macro. -> `//` comments are removed from code lines (`//!` directives are kept).
 *
 * 2. Alias macros. libplacebo binds the hooked texture as `MAINPRESUB` and declares
 *    `#define MAIN_texOff MAINPRESUB_texOff` (object-like macro naming a function-like macro;
 *    the arguments come from the text that follows). Not every GLSL preprocessor rescans that
 *    way. -> Each pass starts with explicit function-like wrappers, e.g.
 *    `#define MAIN_texOff(off) MAINPRESUB_texOff(off)`, guarded by #ifdef so they only apply
 *    where libplacebo actually declared the target.
 */
object ShaderSanitizer {

    /** Bumped when the output changes, so installed copies are regenerated. */
    const val VERSION = 1

    private val SAMPLING = listOf(
        "tex" to "pos",
        "texOff" to "off",
        "gather" to "pos, c"
    )

    fun sanitize(source: String): String {
        val out = StringBuilder(source.length + 1024)
        val lines = source.replace("\r\n", "\n").split('\n')
        var i = 0
        while (i < lines.size) {
            val line = lines[i]
            if (isDirective(line)) {
                // A pass header: a run of //! lines. Copy it, then inject the wrappers.
                val stages = mutableListOf<String>()
                while (i < lines.size && (isDirective(lines[i]) || lines[i].isBlank() && nextIsDirective(lines, i))) {
                    val header = lines[i]
                    Regex("""^\s*//!HOOK\s+(\S+)""").find(header)?.let { stages += it.groupValues[1] }
                    out.append(header).append('\n')
                    i++
                }
                if (stages.isNotEmpty()) out.append(wrappers(stages))
                continue
            }
            out.append(stripComment(line)).append('\n')
            i++
        }
        return out.toString().trimEnd('\n') + "\n"
    }

    private fun isDirective(line: String) = line.trimStart().startsWith("//!")

    private fun nextIsDirective(lines: List<String>, from: Int): Boolean {
        var j = from + 1
        while (j < lines.size && lines[j].isBlank()) j++
        return j < lines.size && isDirective(lines[j])
    }

    /** Removes `//` and single-line `/* */` comments from a code line. GLSL has no strings. */
    internal fun stripComment(line: String): String {
        var result = line.replace(Regex("""/\*.*?\*/"""), " ")
        val idx = result.indexOf("//")
        if (idx >= 0) result = result.substring(0, idx)
        return result.trimEnd()
    }

    /** Texture name libplacebo binds for a hook stage. */
    private fun boundName(stage: String): String = when (stage) {
        "MAIN", "MAINPRESUB", "RGB" -> "MAINPRESUB"
        else -> stage
    }

    private fun wrappers(stages: List<String>): String = buildString {
        fun alias(alias: String, target: String) {
            for ((fn, args) in SAMPLING) {
                appendLine("#ifdef ${target}_$fn")
                appendLine("#undef ${alias}_$fn")
                appendLine("#define ${alias}_$fn($args) ${target}_$fn($args)")
                appendLine("#endif")
            }
        }
        alias("MAIN", "MAINPRESUB")
        stages.map(::boundName).distinct().forEach { alias("HOOKED", it) }
    }
}
